'use strict';
(()=>{
const D=window.CIVIC_DATA;
if(!D){document.getElementById('app').textContent='The app data could not load. Upload the whole website folder, including data.js.';return;}
const AX=[{k:'econ',n:'Economic policy',l:'Market-led',r:'Public-led',w:1.25},{k:'auth',n:'Liberty & authority',l:'Civil liberties',r:'State authority',w:1.2},{k:'culture',n:'Social & cultural',l:'Social change',r:'Traditional norms',w:1.15},{k:'nation',n:'National & global',l:'International cooperation',r:'National priority',w:1},{k:'eco',n:'Environment',l:'Growth-led',r:'Conservation-led',w:.8}];
const KEY='civic-atlas-v1',VIEWS=['home','quiz','results','issues','library','history','compare','lab','saved','about'];
const $=id=>document.getElementById(id), escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=x=>Math.max(0,Math.min(100,Math.round(Number(x)||0)));
const empty=()=>({a:Array(20).fill(null),sk:Array(20).fill(false),issues:{},priority:[],favorites:[],snapshots:[],includeIssues:false,theme:'dark',lastView:'home',savedAt:''});
let state=empty(),view='home',qi=0,issueFilter='All',issueQuery='',issuePage=0,libQuery='',libFilter='All',libPage=0,historyQuery='',historyFilter='All',historyPage=0,compare1='',compare2='',whatIf=null,guest=null,toastTimer=null;
try{const v=JSON.parse(localStorage.getItem(KEY)||'null');if(v&&Array.isArray(v.a)&&v.a.length===20){state={...empty(),...v};state.a=state.a.map(x=>x===null||x===undefined?null:clamp(x));if(!Array.isArray(state.sk)||state.sk.length!==20)state.sk=Array(20).fill(false);if(!state.issues||typeof state.issues!=='object')state.issues={};if(!Array.isArray(state.priority))state.priority=[];if(!Array.isArray(state.favorites))state.favorites=[];if(!Array.isArray(state.snapshots))state.snapshots=[];}}catch(e){console.warn('Could not read local save',e)}
if(state.theme==='light')document.documentElement.classList.add('light');
function persist(){state.savedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){toast('Saving is blocked in this browser; use Export JSON for a backup.')}updateHeader()}
function answered(){return state.a.filter(x=>x!==null).length}
function issuesCount(){return Object.keys(state.issues).filter(k=>Number.isFinite(state.issues[k])).length}
function updateHeader(){$('headerCount').textContent=answered()+' / 20 answered';$('themeBtn').textContent=state.theme==='light'?'☀':'☾'}
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3300)}
function section(eyebrow,title,desc,buttons=''){return `<div class="section-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2><p>${desc}</p></div>${buttons}</div>`}
function btn(text,action,cls='',extra=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`}
function tag(text,cls=''){return `<span class="tag ${cls}">${escape(text)}</span>`}
function findI(name){return D.ideologies.find(i=>i.name===name)}
function questionAxes(answers=state.a,issueData=state.issues,include=state.includeIssues){const scores={},coverage={};
  for(const ax of AX){const arr=D.questions.map((q,i)=>q.axis===ax.k?answers[i]:null).filter(v=>v!==null&&v!==undefined);let base=arr.length?arr.reduce((x,y)=>x+y,0)/arr.length:null;
    const topical=include?D.issues.filter(q=>q.axis===ax.k&&Number.isFinite(issueData[q.id])).map(q=>q.direction===1?50+issueData[q.id]*25:50-issueData[q.id]*25):[];
    if(base===null)base=topical.length?topical.reduce((x,y)=>x+y,0)/topical.length:50;
    else if(topical.length)base=base*.78+(topical.reduce((x,y)=>x+y,0)/topical.length)*.22;
    scores[ax.k]=Math.round(base);coverage[ax.k]=arr.length;
  }return{scores,coverage};}
function rank(scoreData,all=false){const s=scoreData||questionAxes().scores;const coverage=questionAxes().coverage;
 const weights=AX.map(a=>({k:a.k,w:a.w*(coverage[a.k]?1:.22)}));
 const sum=weights.reduce((x,y)=>x+y.w,0);
 return D.ideologies.filter(i=>all||i.eligible!==false).map(i=>{let distance=0;for(let k=0;k<AX.length;k++){const ax=AX[k],diff=s[ax.k]-i.v[k];const w=scoreData?ax.w:weights[k].w;distance+=diff*diff*w}const denom=scoreData?AX.reduce((n,a)=>n+a.w,0):sum;return{...i,similarity:Math.max(0,Math.round(100-Math.sqrt(distance/denom)*1.3)),dist:distance/denom}}).sort((a,b)=>a.dist-b.dist)}
function getTop(){return rank()[0]}
function axisRows(scores=questionAxes().scores){return AX.map(a=>`<div class="axis-row"><div class="axis-title"><span>${a.n}</span><span>${scores[a.k]} / 100</span></div><div class="bar-track"><div class="bar-fill" style="width:${scores[a.k]}%"></div></div><div class="axis-sub"><span>${a.l}</span><span>${a.r}</span></div></div>`).join('')}
function viewsHeader(name){document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===name)});$('breadcrumb').innerHTML=`Your political landscape <span class="sep">/</span> ${escape(({home:'Overview',quiz:'The quiz',results:'My results',issues:"Today's issues",library:'Ideology atlas',history:'Through history',compare:'Compare ideas',lab:'What-if lab',saved:'Save & share',about:'Methods & sources'})[name])}`}
function navigate(dest){if(!VIEWS.includes(dest))dest='home';view=dest;viewsHeader(view);$('app').innerHTML=({home:renderHome,quiz:renderQuiz,results:renderResults,issues:renderIssues,library:renderLibrary,history:renderHistory,compare:renderCompare,lab:renderLab,saved:renderSaved,about:renderAbout})[view]();updateHeader();state.lastView=view;history.replaceState(null,'','#'+view);window.scrollTo({top:0,behavior:'instant'});if(dest==='saved'){$('restoreText')?.focus({preventScroll:true})}if(dest==='issues')updateIssueCountLabel()}
function renderHome(){const a=answered(),n=issuesCount(),top=a>=8?getTop():null;
return `<section class="hero"><div class="hero-content"><div class="eyebrow">YOUR VALUES. YOUR MAP.</div><h1>Politics is more than <em>left and right.</em></h1><p>Discover how your political views fit together, examine the real issues shaping public debate, and explore the traditions behind your ideas. Built for curiosity, not persuasion.</p><div class="row wrap mt-3">${btn(a?'Continue the 20-question quiz ↗':'Start my 20-question quiz ↗','start-quiz','primary')}${btn('Explore today’s issues','go-issues','')}</div><div class="hero-stats"><div><strong>20</strong><span>Core questions</span></div><div><strong>${D.issues.length}</strong><span>Optional issues</span></div><div><strong>${D.ideologies.length}</strong><span>Ideologies & schools</span></div><div><strong>15</strong><span>Policy categories</span></div></div></div></section>
<div class="grid grid-4 mb-3"><div class="stat"><strong>${a}/20</strong><span>Quiz answers saved</span></div><div class="stat"><strong>${n}/75</strong><span>Issue opinions recorded</span></div><div class="stat"><strong>${state.favorites.length}</strong><span>Favorited traditions</span></div><div class="stat"><strong>${state.snapshots.length}</strong><span>Saved snapshots</span></div></div>
${top?`<div class="card gradient mb-3"><div class="row spread wrap"><div><div class="eyebrow">YOUR CURRENT CLOSEST DESCRIPTIVE FIT</div><h2>${escape(top.name)}</h2><p class="muted">${escape(top.desc)}</p>${tag(`${top.similarity}% heuristic similarity`,'accent')}</div>${btn('View full breakdown','go-results','primary')}</div></div>`:`<div class="notice mb-3"><strong>Quick start:</strong> Answer any 8 of the 20 core sliders to unlock a preliminary result. Finish more questions for broader coverage. All 75 in-depth policy issues are completely optional.</div>`}
${section('GO DEEPER','What would you like to explore?','Jump straight to what interests you — you can explore the ideology library without taking the quiz.')}
<div class="grid grid-3"><div class="card feature"><div class="symbol">◈</div><h3>Your worldview report</h3><p class="muted small">See your five dimensions, political map, closest traditions and detailed interpretations.</p><button class="btn small feature-meta" data-action="go-results">Explore my results ↗</button></div><div class="card feature"><div class="symbol">◇</div><h3>The issue desk</h3><p class="muted small">${D.issues.length} real policy debates. Pick just the subjects you care about and record nuance and priorities.</p><button class="btn small feature-meta" data-action="go-issues">Browse issues ↗</button></div><div class="card feature"><div class="symbol">⌛</div><h3>History & ideology</h3><p class="muted small">Compare political traditions and their limited historical parallels, across different eras.</p><button class="btn small feature-meta" data-action="go-history">Open history ↗</button></div><div class="card feature"><div class="symbol">⚗</div><h3>What-if laboratory</h3><p class="muted small">Shift political dimensions and see how descriptive matches change without touching your answers.</p><button class="btn small feature-meta" data-action="go-lab">Try the simulator ↗</button></div><div class="card feature"><div class="symbol">⇄</div><h3>Compare traditions</h3><p class="muted small">Put two ideologies side by side to see similarities and differences across core dimensions.</p><button class="btn small feature-meta" data-action="go-compare">Start comparison ↗</button></div><div class="card feature"><div class="symbol">▤</div><h3>Save your political atlas</h3><p class="muted small">Private device saving, shareable codes, PNG result cards and legacy V5/V6 imports.</p><button class="btn small feature-meta" data-action="go-saved">Save and share ↗</button></div></div>
<div class="notice mt-3">Designed for thoughtful exploration. Political questions have competing interpretations; no automated tool can capture every worldview or infer all beliefs from 20 answers. <a href="#about" data-view="about">Read the methodology.</a></div>`;}
function renderQuiz(){let q=D.questions[qi],a=answered(),v=state.a[qi],pct=Math.round(a/20*100);
return `<div class="quiz-main">${section('CORE VALUES','20 questions. A deeper picture.','Move each slider toward the view you agree with more. Midpoint = a mixed position. Skip anything you are unsure about.')}
<div class="card"><div class="row spread"><strong class="small">Question ${qi+1} of 20</strong>${tag(q.cat,'accent')}</div><div class="progress-track mt-2"><span style="width:${pct}%"></span></div><div class="row spread mt-1"><span class="muted tiny">${a} questions answered</span><span class="muted tiny">${pct}% of quiz answered</span></div></div>
<div class="card quiz-prompt"><div class="eyebrow">${escape(q.cat)} · ${escape(AX.find(x=>x.k===q.axis)?.n||'Values')}</div><h2>${escape(q.q)}</h2><p class="muted">${escape(q.detail)}</p><div class="slider-container"><div class="slider-poles"><div><span class="tag">APPROACH A</span><p class="mt-1">${escape(q.l)}</p></div><div><span class="tag">APPROACH B</span><p class="mt-1">${escape(q.r)}</p></div></div><input class="range" aria-label="Choose your view on ${escape(q.q)}" type="range" id="questionRange" min="0" max="100" step="5" value="${v??50}"><div class="value-row" id="rangeLabel">${v===null?'Move the slider to record your position':`Your position: <span class="score-digits">${v}</span> / 100`}</div></div>
<div class="row wrap spread"><div class="row gap-sm">${btn('← Previous','quiz-prev','small',qi===0?'disabled':'')}${btn('Mixed / middle','quiz-middle','small')}${btn('Skip / unsure','quiz-skip','small subtle')}</div><div class="row gap-sm">${btn(qi===19?'See my results →':'Next →','quiz-next','primary')}</div></div></div>
<div class="card soft"><div class="row spread wrap"><div><h3>Want fewer questions?</h3><p class="muted small">You can see a preliminary result after 8 answered questions. Unanswered sections reduce coverage.</p></div>${btn('Show current results','quiz-finish','small',a<8?'disabled title="Answer at least 8 first"':'')}</div><div class="row spread mt-2"><span class="muted tiny">Private on this device • Autosaves after each change</span>${btn('Restart quiz','quiz-reset','small danger')}</div></div></div>`;}
function compassSvg(scores){const x=31+(100-scores.econ)*2.55,y=31+(100-scores.auth)*2.55;
return `<svg role="img" aria-label="Political orientation map, economics horizontally and civil liberty versus authority vertically" viewBox="0 0 320 320" width="320"><rect x="29" y="29" width="258" height="258" rx="9" fill="var(--panel-2)" stroke="var(--stroke)"/><rect x="29" y="29" width="129" height="129" fill="#8e86ee0d"/><rect x="158" y="29" width="129" height="129" fill="#f5aa6d0b"/><rect x="29" y="158" width="129" height="129" fill="#6de6b010"/><rect x="158" y="158" width="129" height="129" fill="#78a3fa0c"/><path d="M158 29 V287 M29 158 H287" stroke="var(--muted2)" stroke-dasharray="4 5" opacity=".5"/><text x="158" y="16" text-anchor="middle" fill="var(--muted)" font-size="10">More state authority</text><text x="158" y="311" text-anchor="middle" fill="var(--muted)" font-size="10">More civil liberty</text><text x="28" y="303" text-anchor="middle" fill="var(--muted)" font-size="9">↖</text><circle cx="${x}" cy="${y}" r="16" fill="var(--accent)" opacity=".17"/><circle cx="${x}" cy="${y}" r="6" fill="var(--accent)" stroke="var(--ink)" stroke-width="2"/></svg>`}
function radarSvg(scores){let c=160,r=113;const angle=i=>-Math.PI/2+2*Math.PI*i/5,pt=(i,k)=>[c+Math.cos(angle(i))*r*k,c+Math.sin(angle(i))*r*k],str=k=>AX.map((a,i)=>pt(i,k).join(',')).join(' '),val=AX.map((a,i)=>pt(i,(scores[a.k]||0)/100).join(',')).join(' ');
return `<svg viewBox="0 0 320 320" role="img" aria-label="Radar chart of your five political dimensions" width="320">${[.25,.5,.75,1].map(k=>`<polygon points="${str(k)}" fill="none" stroke="var(--stroke)"/>`).join('')}${AX.map((a,i)=>{let p=pt(i,1);let q=pt(i,1.22);return `<path d="M${c},${c} L${p.join(',')}" stroke="var(--stroke)"/><text x="${q[0]}" y="${q[1]}" fill="var(--muted)" text-anchor="middle" font-size="10">${['Economy','Authority','Culture','Nation','Environment'][i]}</text>`}).join('')}<polygon points="${val}" fill="var(--accent)" fill-opacity=".24" stroke="var(--accent)" stroke-width="2.5"/>${AX.map((a,i)=>`<circle cx="${pt(i,scores[a.k]/100)[0]}" cy="${pt(i,scores[a.k]/100)[1]}" r="4" fill="var(--accent)"/>`).join('')}</svg>`}
function buildNarrative(scores){const fragments=[];
for(const ax of AX){let x=scores[ax.k];let d=x<=34?ax.l.toLowerCase():x>=66?ax.r.toLowerCase():'a mixed position';fragments.push(`${ax.n.toLowerCase()}: ${d}`)}return `Your recorded answers currently lean toward ${fragments[0]}, ${fragments[1]}, and ${fragments[2]}. On national and environmental questions, your positions reflect ${fragments[3]} and ${fragments[4]}. These are descriptions of the sliders you moved, not assumptions about your party, personality, or future votes.`}
function matchRow(item,i){return `<div class="library-item"><div class="row" style="gap:12px;min-width:0"><span class="badge-num">${String(i+1).padStart(2,'0')}</span><div><h3>${escape(item.name)}</h3><p>${escape(item.desc)}</p></div></div><div class="right"><span class="match-number">${item.similarity}%</span>${btn('Details','ideology-open','small',`data-name="${escape(item.name)}"`)}</div></div>`}
function renderResults(){const a=answered();if(a<8)return `${section('YOUR PROFILE','Your political map begins here','Answer at least 8 core questions to show a preliminary interpretation. You can still browse all the issues and ideologies right away.')}<div class="empty"><h3>${a}/8 questions needed</h3><p>Complete ${8-a} more core question${8-a===1?'':'s'} to see a first result.</p>${btn('Go to the quiz','go-quiz','primary')}</div>`;
const {scores,coverage}=questionAxes(),res=rank(),best=res[0],n=issuesCount(),high=AX.filter(x=>coverage[x.k]>0).length,topPriorities=state.priority.filter(k=>Number.isFinite(state.issues[k])).map(k=>D.issues.find(x=>x.id===k)).filter(Boolean).slice(0,6);
return `${section('YOUR RESULTS','Your political worldview','A nuanced map based on your answers. Similarity scores compare you with editorial reference profiles — they are not probabilities or endorsements.',`${btn('Save this result','snapshot','small')}${btn('Share / export','go-saved','small primary')}`)}
<div class="grid grid-3 mb-3"><div class="stat"><strong>${a}/20</strong><span>Core questions answered</span></div><div class="stat"><strong>${high}/5</strong><span>Dimensions with responses</span></div><div class="stat"><strong>${n}</strong><span>Optional issue opinions recorded</span></div></div>
<div class="grid grid-2 mb-3"><div class="card gradient"><div class="eyebrow">CLOSEST DESCRIPTIVE MATCH</div><div class="big-match">${escape(best.name)}</div><p class="muted">${escape(best.desc)}</p>${tag(`${best.similarity}% reference similarity`,'accent')}<div class="divider"></div><h4>Illustrative historical parallel</h4><div class="historical"><strong>${escape(best.history.place)}</strong> ${tag(best.history.years)}<p class="muted small mt-1">${escape(best.history.detail)}</p></div><p class="muted tiny mt-2">A historical example is not an exact match, a recommendation, or a judgment about that government.</p></div>
<div class="card"><div class="eyebrow">YOUR VALUES, EXPLAINED</div><h3>Your five political dimensions</h3>${axisRows(scores)}</div></div>
<div class="grid grid-2 mb-3"><div class="card"><h3>Political orientation map</h3><p class="muted small">Horizontal: economic approach. Vertical: civil liberty versus state authority. Other dimensions still matter.</p><div class="chartbox">${compassSvg(scores)}</div></div><div class="card"><h3>Five-axis profile</h3><p class="muted small">Each dimension reflects a different set of questions. A midpoint represents mixed preferences, not a guaranteed neutral position.</p><div class="chartbox">${radarSvg(scores)}</div></div></div>
<div class="card mb-3"><div class="eyebrow">A SHORT READING OF YOUR ANSWERS</div><h3>Your worldview in words</h3><p class="muted">${buildNarrative(scores)}</p>${a<20?`<div class="notice"><strong>Preliminary result:</strong> ${20-a} unanswered questions remain. More answers may change the closest match.</div>`:''}${state.includeIssues?`<p class="muted small mt-2">Optional issue opinions are included at a modest 22% influence where available.</p>`:''}</div>
${section('CLOSEST SCHOOLS','Ten ideologies with nearby profiles','These are distance-based comparisons, not value judgments about which ideologies are better.')}
<div class="grid mb-3">${res.slice(0,10).map(matchRow).join('')}</div>
<div class="grid grid-2 mb-3"><div class="card"><div class="eyebrow">WHERE THE MATCH IS LESS CLOSE</div><h3>Dimensions to explore</h3>${AX.map((x,i)=>({name:x.n,diff:Math.abs(scores[x.k]-best.v[i]),your:scores[x.k],reference:best.v[i]})).sort((a,b)=>b.diff-a.diff).slice(0,3).map(x=>`<div class="mini-list"><div><div class="row spread"><strong>${escape(x.name)}</strong><span class="muted small">Your ${x.your} · Reference ${x.reference}</span></div><p class="muted tiny">Distance: ${x.diff} points on this illustrative scale.</p></div></div>`).join('')}<p class="muted tiny mt-2">Differences do not mean your views contradict one another.</p></div>
<div class="card"><div class="eyebrow">YOUR PERSONAL PRIORITIES</div><h3>Issues you marked important</h3>${topPriorities.length?`<div class="mini-list">${topPriorities.map(x=>`<div><strong>${escape(x.title)}</strong><p class="muted tiny">${escape(positionText(x,state.issues[x.id]))}</p></div>`).join('')}</div>`:`<p class="muted">No issue priorities marked yet. Visit the Issue Desk to mark topics you care about, without answering every question.</p>`}${btn('Visit issue desk','go-issues','small mt-2')}</div></div>
<div class="row wrap">${btn('Compare ideologies','go-compare')}${btn('Try a what-if scenario','go-lab')}${btn('Print profile','print','')}${btn('Save and export','go-saved','primary')}</div>`;}
function positionText(x,v){if(v===null||v===undefined)return 'No stance recorded';if(v===-2)return x.a;if(v===-1)return 'Lean: '+x.a;if(v===0)return 'Mixed / both approaches';if(v===1)return 'Lean: '+x.b;return x.b}
function issueCard(x){let v=state.issues[x.id],saved=Number.isFinite(v),prio=state.priority.includes(x.id);
return `<article class="issue" data-issue-id="${escape(x.id)}"><div class="row spread gap-sm"><span class="tag">${escape(x.category)}</span><button class="priority ${prio?'active':''}" data-action="issue-priority" data-id="${escape(x.id)}" aria-pressed="${prio}">${prio?'★ Priority':'☆ Mark priority'}</button></div><h3>${escape(x.title)}</h3><p>${escape(x.why)}</p><div class="pair"><div><strong>APPROACH A</strong>${escape(x.a)}</div><div><strong>APPROACH B</strong>${escape(x.b)}</div></div><div><div class="label mb-2">Your view (optional)</div><div class="scale-options">${[-2,-1,0,1,2].map((n,i)=>`<button data-action="issue-stance" data-id="${escape(x.id)}" data-value="${n}" title="${['Strongly A','Lean A','Mixed view','Lean B','Strongly B'][i]}" aria-pressed="${saved&&v===n}" class="${saved&&v===n?'active':''}">${['A++','A','MIX','B','B++'][i]}</button>`).join('')}</div><div class="row spread mt-1"><span class="muted tiny"><span class="issue-choice">${escape(positionText(x,v))}</span></span><button class="btn small subtle" data-action="issue-clear" data-id="${escape(x.id)}">Clear</button></div></div><div class="issue-details"><strong>Tradeoff:</strong> ${escape(x.tradeoff)} <span style="float:right"><a href="${escape(x.source)}" target="_blank" rel="noopener noreferrer" aria-label="Read external background on ${escape(x.category)}">Research ↗</a></span></div></article>`}
function filteredIssues(){return D.issues.filter(x=>(issueFilter==='All'||x.category===issueFilter)&&(!issueQuery||[x.title,x.category,x.why,x.tradeoff,x.a,x.b].join(' ').toLowerCase().includes(issueQuery.toLowerCase())))}
function renderIssueList(){const all=filteredIssues(),slice=all.slice(0,(issuePage+1)*9);return `<div class="grid grid-2" id="issuesGrid">${slice.map(issueCard).join('')}</div><div class="page-controls">${all.length>slice.length?btn(`Show more (${all.length-slice.length} remaining)`,'issue-more',''):`<span class="muted small">Showing ${slice.length} of ${all.length} issues</span>`}</div>`}
function renderIssues(){let total=issuesCount();return `${section('ISSUE DESK','The big debates of today','Explore 75 topics across 15 areas. Each card offers two recognizable policy approaches plus middle positions. Everything here is optional.')}
<div class="grid grid-3 issue-stats mb-3"><div class="stat"><strong id="issueAnswered">${total}</strong><span>Positions you've recorded</span></div><div class="stat"><strong id="priorityCount">${state.priority.length}</strong><span>Issues marked important</span></div><div class="stat"><strong>${D.issues.length}</strong><span>Topics to explore at your own pace</span></div></div>
<div class="notice mb-3"><strong>Not a news feed:</strong> These cover major 2026-era policy debates, not breaking headlines or legislation updated in real time. Each issue is simplified to make tradeoffs easy to compare. <a href="#about" data-view="about">Research and limits</a>.</div>
<div class="card mb-3"><div class="row spread wrap"><label class="row" for="includeIssues" style="font-weight:700"><input type="checkbox" id="includeIssues" ${state.includeIssues?'checked':''}> Include my optional policy views in ideology matching</label><span class="muted small">Off by default • up to 22% influence per dimension</span></div></div>
<div class="row adapt mb-2"><input id="issueSearch" class="search" type="search" placeholder="Search issues, e.g. rent, immigration, AI…" value="${escape(issueQuery)}" aria-label="Search issues"><button class="btn small" data-action="issue-only-priority">${issueFilter==='Priority'?'All topics':'My priorities ★'}</button></div>
<div class="filterrow" id="issueFilters">${['All',...D.categories].map(c=>`<button data-action="issue-filter" data-filter="${escape(c)}" class="${issueFilter===c?'active':''}">${escape(c)}</button>`).join('')}</div><div id="issueResults">${renderIssueList()}</div>`}
function updateIssueCountLabel(){if($('issueAnswered'))$('issueAnswered').textContent=issuesCount();if($('priorityCount'))$('priorityCount').textContent=state.priority.length}
function filteredIdeologies(){let arr=D.ideologies.filter(i=>(libFilter==='All'||libFilter==='Favorites'&&state.favorites.includes(i.name)||libFilter==='Broad matches'&&i.eligible!==false)&&(!libQuery||[i.name,i.desc,i.history.place].join(' ').toLowerCase().includes(libQuery.toLowerCase())));return arr}
function renderLibraryList(){let arr=filteredIdeologies(),slice=arr.slice(libPage*12,libPage*12+12);return `<div class="grid">${slice.map(i=>`<div class="library-item"><div><h3>${escape(i.name)} ${i.eligible===false?tag('Historical / specialized'):''}</h3><p>${escape(i.desc)}</p><span class="muted tiny">Historical parallel: ${escape(i.history.place)} · ${escape(i.history.years)}</span></div><div class="right"><button class="btn small" data-action="favorite" data-name="${escape(i.name)}" aria-label="Favorite ${escape(i.name)}">${state.favorites.includes(i.name)?'★':'☆'}</button>${btn('Explore','ideology-open','small',`data-name="${escape(i.name)}"`)}</div></div>`).join('')}</div><div class="page-controls"><button class="btn small" data-action="library-prev" ${libPage===0?'disabled':''}>← Previous</button><span class="muted small">${arr.length?libPage*12+1:0}–${Math.min(arr.length,libPage*12+12)} of ${arr.length}</span><button class="btn small" data-action="library-next" ${(libPage+1)*12>=arr.length?'disabled':''}>Next →</button></div>`}
function renderLibrary(){return `${section('IDEOLOGY ATLAS','A wider world of political thought','Explore 158 ideologies, institutions, movements, and policy traditions. Some are broad worldviews; others are specialized or historical. Not all are candidates for automatic quiz matching.')}
<div class="card mb-3"><div class="row adapt"><input class="search" id="libSearch" type="search" placeholder="Search by ideology, idea, or historical example…" value="${escape(libQuery)}" aria-label="Search ideologies"><span class="tag">${D.ideologies.length} unique entries</span></div><div class="filterrow mt-2">${['All','Broad matches','Favorites'].map(x=>`<button data-action="library-filter" data-filter="${x}" class="${libFilter===x?'active':''}">${x}</button>`).join('')}</div></div><div id="libraryResults">${renderLibraryList()}</div>`}
function ideologyModal(name){const x=findI(name);if(!x)return;const h=x.history;
$('modal').innerHTML=`<div class="row spread"><span class="eyebrow">POLITICAL TRADITION</span><button class="btn small" data-action="modal-close" aria-label="Close dialog">✕</button></div><h2>${escape(x.name)}</h2><p class="muted">${escape(x.desc)}</p><div class="row wrap mb-2">${tag(x.eligible===false?'Specialized / historical tradition':'Available as a descriptive quiz match')}${state.favorites.includes(name)?tag('★ Favorited','gold'):''}</div><div class="divider"></div><h3>Illustrative value coordinates</h3>${AX.map((ax,j)=>`<div class="axis-row"><div class="axis-title"><span>${ax.n}</span><span>${x.v[j]}</span></div><div class="bar-track"><div class="bar-fill" style="width:${x.v[j]}%"></div></div><div class="axis-sub"><span>${ax.l}</span><span>${ax.r}</span></div></div>`).join('')}<div class="divider"></div><h3>Historical reference</h3><div class="historical"><strong>${escape(h.place)}</strong> · ${tag(h.years)}<p class="muted small mt-2">${escape(h.detail)}</p></div><p class="muted tiny mt-2">A historical movement or government may illustrate only one part of the tradition. The app does not endorse it, nor claim an exact fit.</p><div class="row wrap mt-2"><button class="btn primary" data-action="favorite" data-name="${escape(name)}">${state.favorites.includes(name)?'★ Remove favorite':'☆ Favorite this tradition'}</button><button class="btn" data-action="compare-from-modal" data-name="${escape(name)}">Compare →</button></div>`;$('modalBackdrop').classList.remove('hidden');$('modal').focus()}
function parseStart(years){const m=String(years).match(/\d{4}/);return m?Number(m[0]):9999}
function filteredHistory(){return D.ideologies.filter(x=>{const y=parseStart(x.history.years);return (historyFilter==='All'||historyFilter==='Before 1900'&&y<1900||historyFilter==='1900–1945'&&y>=1900&&y<=1945||historyFilter==='1946–1989'&&y>=1946&&y<=1989||historyFilter==='1990–present'&&y>=1990&&y!==9999||historyFilter==='No country'&&y===9999)&&(!historyQuery||[x.name,x.history.place,x.history.years,x.history.detail].join(' ').toLowerCase().includes(historyQuery.toLowerCase()))}).sort((a,b)=>parseStart(a.history.years)-parseStart(b.history.years))}
function renderHistoryList(){const all=filteredHistory(),slice=all.slice(historyPage*13,historyPage*13+13);return `${slice.map(x=>`<div class="history-item"><div class="year">${escape(x.history.years)}</div><div><h3>${escape(x.history.place)}</h3><div class="small">${escape(x.name)}</div><p class="muted small">${escape(x.history.detail)}</p>${btn('Explore ideology','ideology-open','small',`data-name="${escape(x.name)}"`)}</div></div>`).join('')}<div class="page-controls"><button class="btn small" data-action="history-prev" ${historyPage===0?'disabled':''}>← Previous</button><span class="muted small">${all.length?historyPage*13+1:0}–${Math.min((historyPage+1)*13,all.length)} of ${all.length}</span><button class="btn small" data-action="history-next" ${(historyPage+1)*13>=all.length?'disabled':''}>Next →</button></div>`}
function renderHistory(){return `${section('TIME & IDEAS','Ideas through history','Browse government periods, movements and policy experiments associated with each political tradition. The historical periods are illustrative and may cover only part of the doctrine.')}
<div class="notice mb-3"><strong>Important:</strong> A country can combine different ideologies over time. An historical association is not a claim that the entire country represented that ideology, nor is it praise for the regime.</div>
<div class="card mb-3"><input class="search" id="historySearch" value="${escape(historyQuery)}" type="search" placeholder="Find a country, ideology, or era…" aria-label="Search historical parallels"><div class="filterrow mt-2">${['All','Before 1900','1900–1945','1946–1989','1990–present','No country'].map(x=>`<button data-action="history-filter" data-filter="${x}" class="${historyFilter===x?'active':''}">${x}</button>`).join('')}</div></div><div id="historyResults">${renderHistoryList()}</div>`}
function makeSelect(id,selected){return `<select class="select" id="${id}" aria-label="Select an ideology">${D.ideologies.map(x=>`<option value="${escape(x.name)}" ${selected===x.name?'selected':''}>${escape(x.name)}</option>`).join('')}</select>`}
function renderCompare(){if(!compare1)compare1=answered()>=8?getTop().name:'Social democracy';if(!compare2)compare2='Classical liberalism';let a=findI(compare1)||D.ideologies[0],b=findI(compare2)||D.ideologies[1];return `${section('IDEA COMPARATOR','Two traditions. Five dimensions.','Compare reference points and historical contexts. This is descriptive, not a verdict about which tradition is preferable.')}
<div class="grid grid-2 mb-3"><div class="card"><span class="label">FIRST TRADITION</span>${makeSelect('compareA',a.name)}</div><div class="card"><span class="label">SECOND TRADITION</span>${makeSelect('compareB',b.name)}</div></div>
<div class="compare-grid mb-3"><div class="card"><div class="compare-head"><div class="eyebrow">TRADITION A</div><h2>${escape(a.name)}</h2><p class="muted small">${escape(a.desc)}</p></div><div class="historical"><h4>${escape(a.history.place)}</h4>${tag(a.history.years)}<p class="muted small mt-1">${escape(a.history.detail)}</p></div></div>
<div class="card"><div class="compare-head"><div class="eyebrow">TRADITION B</div><h2>${escape(b.name)}</h2><p class="muted small">${escape(b.desc)}</p></div><div class="historical"><h4>${escape(b.history.place)}</h4>${tag(b.history.years)}<p class="muted small mt-1">${escape(b.history.detail)}</p></div></div></div>
<div class="card"><h3>Side-by-side values</h3><div class="compare-axis"><span class="muted small">${escape(a.name)}</span><strong style="text-align:center">Dimension</strong><span class="muted small" style="text-align:right">${escape(b.name)}</span></div>${AX.map((x,i)=>`<div class="compare-axis"><div class="leftscore"><strong>${a.v[i]}</strong><div class="bar-track"><div class="bar-fill" style="width:${a.v[i]}%"></div></div></div><div class="muted tiny" style="text-align:center">${x.n}</div><div><strong>${b.v[i]}</strong><div class="bar-track"><div class="bar-fill" style="width:${b.v[i]}%"></div></div></div></div>`).join('')}</div>
<div class="notice mt-2"><strong>Reading the difference:</strong> The largest reference-point gap here is in ${AX.map((x,i)=>({n:x.n,d:Math.abs(a.v[i]-b.v[i])})).sort((x,y)=>y.d-x.d)[0].n.toLowerCase()}. A single score does not capture each tradition's internal debates or historical variety.</div>`}
function renderLab(){if(!whatIf)whatIf=questionAxes().scores;return `${section('WHAT-IF LAB','Experiment without changing your answers','Try a different set of values and see which political reference profiles are nearby. This simulation never overwrites your quiz.')}
<div class="grid grid-2"><div class="card"><h3>Change the five dimensions</h3><p class="muted small">Move the controls as much as you like.</p>${AX.map(x=>`<div class="axis-row"><div class="axis-title"><span>${x.n}</span><strong id="labValue-${x.k}">${whatIf[x.k]}</strong></div><input type="range" class="range labRange" min="0" max="100" step="1" data-axis="${x.k}" value="${whatIf[x.k]}" aria-label="Experiment with ${x.n}"><div class="axis-sub"><span>${x.l}</span><span>${x.r}</span></div></div>`).join('')}<div class="row wrap mt-3">${btn('Use my quiz values','lab-reset','small')}${btn('Reset to middle','lab-middle','small')}</div></div><div class="card"><div class="eyebrow">LIVE EXPERIMENT</div><div id="labPrediction">${labPrediction()}</div></div></div>`}
function labPrediction(){const r=rank(whatIf),top=r[0];return `<h2 class="big-match">${escape(top.name)}</h2><p class="muted">${escape(top.desc)}</p>${tag(`${top.similarity}% reference similarity`,'accent')}<div class="divider"></div><h3>Other nearby reference points</h3><div class="mini-list">${r.slice(1,5).map(x=>`<div class="row spread"><strong>${escape(x.name)}</strong><span class="muted">${x.similarity}%</span></div>`).join('')}</div><div class="divider"></div><h3>Historical parallel</h3><p class="muted small">${escape(top.history.place)} · ${escape(top.history.years)} — ${escape(top.history.detail)}</p><p class="tiny muted">Simulation scores are invented teaching coordinates, not scientifically validated measures.</p>`}
function serialize(){const payload={v:1,a:state.a,sk:state.sk,p:state.issues,priority:state.priority,includeIssues:state.includeIssues};const raw=JSON.stringify(payload);const bytes=new TextEncoder().encode(raw);let bin='';for(const b of bytes)bin+=String.fromCharCode(b);return 'CIVICATLAS1:'+btoa(bin).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function parseCode(input){input=input.trim();let payload;
const match=input.match(/(CIVICATLAS1|POLATLAS5|POLATLAS3|POLITICS-V2):([A-Za-z0-9+/_=-]+)/);
if(match){let raw=match[2].replace(/-/g,'+').replace(/_/g,'/');while(raw.length%4)raw+='=';let bytes=Uint8Array.from(atob(raw),c=>c.charCodeAt(0));payload=JSON.parse(new TextDecoder().decode(bytes));if(match[1]==='CIVICATLAS1'){if(payload.v!==1)throw Error('Unsupported Civic Atlas code.');}
else if(match[1]==='POLITICS-V2'){if(payload.version!==2||!Array.isArray(payload.values)||payload.values.length!==16)throw Error('Invalid V2 code.');payload={a:[...payload.values,...Array(4).fill(null)],sk:Array(20).fill(false),p:{},priority:[]};}
else {if(![3,5].includes(payload.v)||!Array.isArray(payload.a)||payload.a.length!==20)throw Error('Invalid historical Political Atlas code.');payload={a:payload.a.map((x,i)=>Array.isArray(payload.t)&&!payload.t[i]?null:x),sk:Array(20).fill(false),p:{},priority:[]};}}
else if(input.startsWith('{')){payload=JSON.parse(input);if(payload.format==='political-atlas-v5'&&Array.isArray(payload.answers)){payload={a:payload.answers.map((x,i)=>Array.isArray(payload.visited)&&!payload.visited[i]?null:x),sk:Array(20).fill(false),p:{},priority:[]}}else if(payload.format==='civic-atlas-export')payload=payload.profile||payload;}
else throw Error('No recognized code. Paste a Civic Atlas, Political Atlas V3/V5/V6 code, or exported JSON.');
if(!Array.isArray(payload.a)||payload.a.length!==20||!payload.a.every(x=>x===null||Number.isFinite(x)&&x>=0&&x<=100))throw Error('Invalid answer data; expected 20 positions.');
let legal=new Set(D.issues.map(x=>x.id)),p={};if(payload.p&&typeof payload.p==='object')for(const [k,v] of Object.entries(payload.p))if(legal.has(k)&&Number.isInteger(v)&&v>=-2&&v<=2)p[k]=v;
let priorities=Array.isArray(payload.priority)?payload.priority.filter(x=>legal.has(x)).slice(0,75):[];
return{a:payload.a.map(x=>x===null?null:clamp(x)),sk:Array.isArray(payload.sk)&&payload.sk.length===20?payload.sk.map(Boolean):Array(20).fill(false),issues:p,priority:priorities,includeIssues:payload.includeIssues===true};}
function applyImport(raw,asGuest=false){const parsed=parseCode(raw);if(asGuest){guest=parsed;toast('Comparison profile loaded.');navigate('saved');return}state={...state,...parsed};qi=Math.max(0,state.a.findIndex(x=>x===null));if(qi<0)qi=0;persist();toast('Answers and issue positions restored.');navigate(answered()>=8?'results':'quiz')}
function downloadFile(filename,text,mime='application/json'){const blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1800)}
function exportJSON(){downloadFile('Civic_Atlas_Profile.json',JSON.stringify({format:'civic-atlas-export',exported:new Date().toISOString(),profile:{a:state.a,sk:state.sk,p:state.issues,priority:state.priority,includeIssues:state.includeIssues},explanation:'All values are stored on your device, not on a server.'},null,2))}
function snapshot(){if(answered()<8){toast('Answer at least 8 questions to save a result.');return}const entry={time:new Date().toISOString(),a:[...state.a],issues:{...state.issues},includeIssues:state.includeIssues,top:getTop().name};state.snapshots.unshift(entry);state.snapshots=state.snapshots.slice(0,12);persist();toast('This result was saved on your device.');navigate('saved')}
function canvasExport(){if(answered()<8){toast('Answer 8 questions first.');return}const scores=questionAxes().scores,top=getTop(),canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1080;const c=canvas.getContext('2d');const grad=c.createLinearGradient(0,0,1080,1080);grad.addColorStop(0,'#0b1b2a');grad.addColorStop(1,'#112d39');c.fillStyle=grad;c.fillRect(0,0,1080,1080);c.fillStyle='#6ce2b8';c.font='800 40px Arial';c.fillText('◈ CIVIC ATLAS',72,110);c.fillStyle='#a1b8c7';c.font='28px Arial';c.fillText('MY POLITICAL WORLDVIEW',72,208);c.fillStyle='#eff9fb';c.font='bold 66px Arial';const wrap=(text,maxWidth)=>{const words=text.split(' ');let lines=[],line='';for(let w of words){let test=line?line+' '+w:w;if(c.measureText(test).width>maxWidth&&line){lines.push(line);line=w}else line=test}if(line)lines.push(line);return lines};wrap(top.name,920).forEach((t,i)=>c.fillText(t,72,300+i*78));let sy=475;c.font='24px Arial';AX.forEach((ax,i)=>{let y=sy+i*89;c.fillStyle='#b8c7d4';c.fillText(ax.n,72,y);c.fillStyle='#243e50';c.fillRect(72,y+14,790,17);c.fillStyle='#6ce2b8';c.fillRect(72,y+14,Math.round(scores[ax.k]/100*790),17);c.fillStyle='#edf4f8';c.fillText(`${scores[ax.k]}`,888,y+29)});c.font='20px Arial';c.fillStyle='#99acbb';c.fillText('Educational comparison • Not a scientific diagnosis',72,999);canvas.toBlob(blob=>{if(!blob){toast('Could not create PNG.');return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='My_Civic_Atlas_Result.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)},'image/png')}
function guestComparison(){if(!guest||answered()<8)return '';const cur=questionAxes().scores,other=questionAxes(guest.a,guest.issues,guest.includeIssues).scores,r=rank(other)[0];return `<div class="card mt-2"><h3>Loaded comparison profile</h3><div class="row wrap">${tag('Their nearest profile: '+r.name,'accent')}${tag(guest.a.filter(v=>v!==null).length+' core answers')}</div>${AX.map(x=>`<div class="compare-axis"><div class="leftscore"><strong>${cur[x.k]}</strong><div class="bar-track"><div class="bar-fill" style="width:${cur[x.k]}%"></div></div></div><div class="muted tiny" style="text-align:center">${x.n}</div><div><strong>${other[x.k]}</strong><div class="bar-track"><div class="bar-fill" style="width:${other[x.k]}%"></div></div></div></div>`).join('')}<p class="muted tiny mt-2">Left: your current view. Right: imported view. Only display on this device; no comparison is uploaded.</p></div>`}
function renderSaved(){let code=serialize(),a=answered(),best=a>=8?getTop():null;return `${section('YOUR PRIVATE ATLAS','Save, restore & share','Everything stays on your device unless you choose to copy or export it. Your browser may erase local storage, so keep a backup code.')}
<div class="grid grid-2 mb-3"><div class="card"><div class="eyebrow">YOUR CURRENT RESULT CODE</div><h3>Copy and restore anytime</h3><p class="muted small">Includes every core slider and optional issue position. You can send the code to a friend or paste it into this app on another device.</p><div class="codebox" id="currentCode">${escape(code)}</div><div class="row wrap mt-2">${btn('Copy my code','copy-code','primary')}${btn('Share code','share-code')}${btn('Download JSON','download-json')}</div></div>
<div class="card"><div class="eyebrow">YOUR PROFILE</div><h3>${best?escape(best.name):'Answer eight questions first'}</h3><p class="muted">${a}/20 core values · ${issuesCount()} detailed issue positions · ${state.priority.length} priorities</p><p class="muted small">${best?`Your present reference similarity: ${best.similarity}% (heuristic).`:'Your answers still save even before you finish the core quiz.'}</p><div class="row wrap mt-2">${btn('Download image card','export-png','small',a<8?'disabled':'')}${btn('Print / save PDF','print','small',a<8?'disabled':'')}${btn('Save snapshot','snapshot','small',a<8?'disabled':'')}</div></div></div>
<div class="grid grid-2 mb-3"><div class="card"><h3>Restore a profile</h3><p class="muted small">Paste a Civic Atlas code, Political Atlas V5/V6 code, V3 code, V2 code, or saved JSON. Restoring here replaces your current answers.</p><textarea class="textarea" id="restoreText" placeholder="Paste your saved code or JSON here…" spellcheck="false"></textarea><div class="row wrap mt-2">${btn('Restore my profile','restore','primary')}<label class="btn" for="loadProfile">Import JSON file</label><input type="file" id="loadProfile" accept=".json,.txt" hidden></div></div>
<div class="card"><h3>Compare with someone else's code</h3><p class="muted small">Paste another saved result to compare the five dimension values without overwriting your own answers.</p><textarea class="textarea" id="guestText" placeholder="Paste a friend's Civic Atlas code…" spellcheck="false"></textarea>${btn('Compare profiles','guest-import','mt-2',a<8?'disabled':'')}${guestComparison()}</div></div>
<div class="card mb-3"><div class="row spread wrap"><div><h3>Saved snapshots</h3><p class="muted small">Keep a small on-device history of how your own answers change over time.</p></div>${btn('Save current snapshot','snapshot','small',a<8?'disabled':'')}</div>${state.snapshots.length?`<div class="mini-list mt-2">${state.snapshots.map((x,i)=>`<div class="row spread wrap"><div><strong>${escape(x.top||'Saved result')}</strong><p class="muted tiny">${new Date(x.time).toLocaleString()} · ${x.a.filter(v=>v!==null).length} answered</p></div><div class="row gap-sm">${btn('Restore','snapshot-load','small',`data-idx="${i}"`)}${btn('Delete','snapshot-delete','small danger',`data-idx="${i}"`)}</div></div>`).join('')}</div>`:`<div class="muted small">No snapshots yet.</div>`}</div>
<div class="card"><h3>Privacy & controls</h3><p class="muted small">This is a fully client-side app with no analytics, login, ads or data collection. A share code contains your answers; only share it with people you trust. GitHub Pages hosting serves the website files, not your stored results.</p><div class="row wrap mt-2">${btn('Clear my answers and saved data','erase-all','danger')}${btn('Switch color theme','theme-toggle')}</div></div>`}
function renderAbout(){const sourceEntries=[['Issue topics: Pew, 2026','https://www.pewresearch.org/politics/2026/10/08/economy-ranks-as-top-issue-in-midterms-for-all-voters-but-partisans-differ-over-the-importance-of-other-issues/'],['Political typology background (Pew, 2026)','https://www.pewresearch.org/collections/political-typology/'],['National problems and public concerns (Pew, 2025)','https://www.pewresearch.org/politics/2025/02/20/americans-continue-to-view-several-economic-issues-as-top-national-problems/'],['American issue priorities (AP-NORC, 2025)','https://apnorc.org/projects/2025-the-publics-priorities-and-expectations/'],['GitHub Pages publishing guide','https://docs.github.com/en/pages/getting-started-with-github-pages/configuring-a-publishing-source-for-your-github-pages-site'],['Apple: Add web app to Home Screen','https://support.apple.com/guide/iphone/iphea86e5236/ios']];
return `${section('TRANSPARENCY','How the atlas works','This is an educational, independent tool with editorial approximations. It is not affiliated with a polling organization, a party or a government.')}
<div class="grid grid-2 mb-3"><div class="card"><h3>Core quiz</h3><p class="muted">Twenty slider questions across five dimensions: economics; liberty and state authority; social values; international versus national focus; environment. You can view a preliminary result after eight.</p><p class="muted small">Each axis is the average of answered questions within that area. Unanswered dimensions are displayed at 50 but are down-weighted when finding a match.</p></div><div class="card"><h3>Matching</h3><p class="muted">We compare your five coordinates with reference coordinates written for ${D.ideologies.length} political traditions. A weighted distance produces an approximate similarity score. It is not a survey probability, scientific classification, electoral recommendation, or objective measure of political correctness.</p><p class="muted small">Some highly specific ideologies cannot be reliably detected from broad slider responses, so they appear in the library but are excluded from automatic closest-match assignment.</p></div><div class="card"><h3>Optional issue opinions</h3><p class="muted">${D.issues.length} issue cards span ${D.categories.length} topics. Each is described as competing policy approaches with a middle option and a tradeoff. The positions are simplified; many more approaches and combinations exist.</p><p class="muted small">Issue answers do not affect matching unless you enable the option in the Issue Desk. With it enabled, they contribute up to 22% of any affected axis. Marking an issue as important changes your report's priorities, not its numerical weight.</p></div><div class="card"><h3>Historical comparisons</h3><p class="muted">A named government, period or movement is an illustration of selected institutions or ideas, not an exact match with an ideology. No country embodies a complete school of thought. A few traditions have no credible country-level parallel.</p><p class="muted small">Some historical examples include coercive or abusive regimes. Their inclusion is strictly for historical explanation, not approval.</p></div></div>
<div class="card mb-3"><h3>Limits & editorial neutrality</h3><p class="muted">Political concepts vary across countries, languages and historical periods. The app cannot literally represent every political view, and its current-issue library is not a real-time news service. Questions should be considered starting points for discussion, not exhaustive descriptions of problems or solutions. You should not use its scores to judge anyone's worth, character, or vote.</p><p class="muted">Policy controversies often have more than two plausible positions. Approach A and B are illustrative endpoints rather than labels such as “good” or “bad.” Historical data and contemporary issue framing should be verified with reliable sources when stakes are high.</p><span class="tag">Issue library curated: November 2026</span></div>
${section('FURTHER READING','Selected references','External sources for background and context. Their research methodologies differ from this app.')}
<div class="source-list mb-3">${sourceEntries.map(([name,url])=>`<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(name)} <span>${escape(new URL(url).hostname)} ↗</span></a>`).join('')}</div><div class="card"><h3>All issue subject sources</h3><div class="source-list">${D.categories.map(cat=>{const url=D.issues.find(x=>x.category===cat).source;return `<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(cat)} <span>${escape(new URL(url).hostname)} ↗</span></a>`}).join('')}</div></div>`}
function goPageFromAction(action){const map={'go-home':'home','go-quiz':'quiz','go-results':'results','go-issues':'issues','go-library':'library','go-history':'history','go-compare':'compare','go-lab':'lab','go-saved':'saved','go-about':'about'};if(map[action]){navigate(map[action]);return true}return false}
function questionNext(){if(qi>=19){if(answered()>=8)navigate('results');else toast('You need at least 8 answered questions for a result.');return}qi++;navigate('quiz')}
function issueUpdateCard(id){const card=document.querySelector(`.issue[data-issue-id="${id}"]`);if(!card)return;let v=state.issues[id],x=D.issues.find(x=>x.id===id),p=state.priority.includes(id);card.querySelectorAll('[data-action="issue-stance"]').forEach(b=>{let a=Number(b.dataset.value)===v;b.classList.toggle('active',a);b.setAttribute('aria-pressed',String(a))});card.querySelector('.issue-choice').textContent=positionText(x,v);const pr=card.querySelector('[data-action="issue-priority"]');pr.classList.toggle('active',p);pr.textContent=p?'★ Priority':'☆ Mark priority';pr.setAttribute('aria-pressed',String(p));updateIssueCountLabel()}
async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text)}else{const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.append(ta);ta.select();if(!document.execCommand('copy'))throw Error('Clipboard unavailable');ta.remove()}toast('Copied to clipboard.')}catch(e){toast('Could not copy automatically. Select the code and copy it manually.')}}
function handleClick(ev){const nav=ev.target.closest('[data-view]');if(nav){ev.preventDefault();navigate(nav.dataset.view);return}const el=ev.target.closest('[data-action]');if(!el)return;const act=el.dataset.action;ev.preventDefault();if(goPageFromAction(act))return;
switch(act){case 'start-quiz':qi=Math.max(0,state.a.findIndex(x=>x===null));if(qi<0)qi=0;navigate('quiz');return;
case 'quiz-prev':if(qi>0)qi--;navigate('quiz');return;
case 'quiz-next':questionNext();return;
case 'quiz-middle':state.a[qi]=50;state.sk[qi]=false;persist();questionNext();return;
case 'quiz-skip':state.a[qi]=null;state.sk[qi]=true;persist();questionNext();return;
case 'quiz-finish':if(answered()<8)toast('Answer at least 8 questions first.');else navigate('results');return;
case 'quiz-reset':if(confirm('Restart the 20-question quiz? Optional issue answers and favorites will stay saved.')){state.a=Array(20).fill(null);state.sk=Array(20).fill(false);qi=0;persist();navigate('quiz')}return;
case 'issue-stance':{let id=el.dataset.id,value=Number(el.dataset.value);state.issues[id]=value;persist();issueUpdateCard(id);return}
case 'issue-clear':delete state.issues[el.dataset.id];persist();issueUpdateCard(el.dataset.id);return;
case 'issue-priority':{let id=el.dataset.id,i=state.priority.indexOf(id);if(i>=0)state.priority.splice(i,1);else state.priority.push(id);persist();issueUpdateCard(id);return}
case 'issue-filter':issueFilter=el.dataset.filter;issuePage=0;navigate('issues');return;
case 'issue-only-priority':issueFilter=issueFilter==='Priority'?'All':'Priority';issuePage=0;navigate('issues');return;
case 'issue-more':issuePage++;$('issueResults').innerHTML=renderIssueList();return;
case 'library-filter':libFilter=el.dataset.filter;libPage=0;navigate('library');return;
case 'library-prev':libPage=Math.max(0,libPage-1);$('libraryResults').innerHTML=renderLibraryList();return;
case 'library-next':libPage++;$('libraryResults').innerHTML=renderLibraryList();return;
case 'favorite':{let name=el.dataset.name,i=state.favorites.indexOf(name);if(i<0)state.favorites.push(name);else state.favorites.splice(i,1);persist();if(!$('modalBackdrop').classList.contains('hidden'))ideologyModal(name);else navigate(view);toast(i<0?'Added to favorites.':'Removed from favorites.');return}
case 'ideology-open':ideologyModal(el.dataset.name);return;
case 'modal-close':$('modalBackdrop').classList.add('hidden');return;
case 'compare-from-modal':compare1=el.dataset.name;$('modalBackdrop').classList.add('hidden');navigate('compare');return;
case 'history-filter':historyFilter=el.dataset.filter;historyPage=0;navigate('history');return;
case 'history-prev':historyPage=Math.max(0,historyPage-1);$('historyResults').innerHTML=renderHistoryList();return;
case 'history-next':historyPage++;$('historyResults').innerHTML=renderHistoryList();return;
case 'lab-reset':whatIf=questionAxes().scores;navigate('lab');return;
case 'lab-middle':whatIf=Object.fromEntries(AX.map(x=>[x.k,50]));navigate('lab');return;
case 'snapshot':snapshot();return;
case 'copy-code':copyText(serialize());return;
case 'share-code':{const code=serialize(),text=`My Civic Atlas political worldview code:\n${code}\nOpen Civic Atlas and paste it into Save & share to view the profile.`;if(navigator.share)navigator.share({title:'My Civic Atlas profile',text}).catch(()=>{});else copyText(text);return}
case 'download-json':exportJSON();return;
case 'export-png':canvasExport();return;
case 'print':window.print();return;
case 'restore':try{applyImport($('restoreText').value)}catch(e){toast('Import failed: '+e.message)}return;
case 'guest-import':try{applyImport($('guestText').value,true)}catch(e){toast('Compare failed: '+e.message)}return;
case 'snapshot-load':{const entry=state.snapshots[Number(el.dataset.idx)];if(!entry)return;if(!confirm('Restore this earlier quiz result? Current answers will be replaced.'))return;state.a=[...entry.a];state.issues={...entry.issues};state.includeIssues=!!entry.includeIssues;persist();navigate('results');return}
case 'snapshot-delete':{let idx=Number(el.dataset.idx);state.snapshots.splice(idx,1);persist();navigate('saved');return}
case 'theme-toggle':toggleTheme();navigate('saved');return;
case 'erase-all':if(confirm('Delete your quiz answers, opinions, favorites, and snapshots from this browser? This cannot be undone.')){let theme=state.theme;state=empty();state.theme=theme;guest=null;whatIf=null;qi=0;persist();navigate('home');toast('Local data cleared.')}return;
default:return;}}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';document.documentElement.classList.toggle('light',state.theme==='light');persist()}
function handleInput(ev){let el=ev.target;
if(el.id==='questionRange'){let v=clamp(el.value);state.a[qi]=v;state.sk[qi]=false;$('rangeLabel').innerHTML=`Your position: <span class="score-digits">${v}</span> / 100`;persist();$('app').querySelector('.progress-track span').style.width=Math.round(answered()/20*100)+'%';return}
if(el.id==='issueSearch'){issueQuery=el.value;issuePage=0;$('issueResults').innerHTML=renderIssueList();return}
if(el.id==='libSearch'){libQuery=el.value;libPage=0;$('libraryResults').innerHTML=renderLibraryList();return}
if(el.id==='historySearch'){historyQuery=el.value;historyPage=0;$('historyResults').innerHTML=renderHistoryList();return}
if(el.classList.contains('labRange')){whatIf[el.dataset.axis]=clamp(el.value);const n=$('labValue-'+el.dataset.axis);if(n)n.textContent=String(whatIf[el.dataset.axis]);$('labPrediction').innerHTML=labPrediction();return}}
function handleChange(ev){const el=ev.target;if(el.id==='includeIssues'){state.includeIssues=el.checked;persist();toast(el.checked?'Your optional issue views now influence matching slightly.':'Optional issue views no longer influence matching.');return}
if(el.id==='compareA'){compare1=el.value;navigate('compare');return}if(el.id==='compareB'){compare2=el.value;navigate('compare');return}
if(el.id==='loadProfile'){const file=el.files?.[0];if(!file)return;if(file.size>1000000){toast('This file is too large.');return}file.text().then(s=>applyImport(s)).catch(e=>toast('Import failed: '+e.message));el.value='';return}}
$('themeBtn').addEventListener('click',()=>{toggleTheme();updateHeader()});document.body.addEventListener('click',handleClick);document.body.addEventListener('input',handleInput);document.body.addEventListener('change',handleChange);$('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))$('modalBackdrop').classList.add('hidden')});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('modalBackdrop').classList.add('hidden')});
// A Priority-only filter is implemented separately because it is a user-owned subset.
const baseFilteredIssues=filteredIssues;filteredIssues=function(){let all=baseFilteredIssues();if(issueFilter==='Priority')all=D.issues.filter(x=>state.priority.includes(x.id)&&(!issueQuery||[x.title,x.category,x.why,x.tradeoff,x.a,x.b].join(' ').toLowerCase().includes(issueQuery.toLowerCase())));return all};
updateHeader();let initial=location.hash.slice(1);if(!VIEWS.includes(initial))initial='home';navigate(initial);
if('serviceWorker'in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('Offline caching is unavailable',e)));
})();
